import { mkdir, readFile, writeFile } from 'node:fs/promises';

const sourceFiles = [
  'src/core/EventBus.js',
  'src/core/GameState.js',
  'src/battle/StatusEngine.js',
  'src/battle/Unit.js',
  'src/battle/ActionResolver.js',
  'src/battle/CTBEngine.js',
  'src/database/ff5Database.js',
  'src/battle/EquipmentSystem.js',
  'src/database/battleCatalog.js',
  'src/services/FirebaseAccountService.js',
  'src/data/abilityData.js',
  'src/data/partyData.js',
  'src/data/bossData.js',
  'src/database/ff5BossTechniques.js',
  'src/battle/BossActionProfiles.js',
  'src/ui/MessageWindow.js',
  'src/battle/BattleManager.js',
  'src/ui/BattleEffectRegistry.js',
  'src/ui/BattleUI.js',
  'src/ui/IntermissionUI.js',
  'src/main.js',
];

const chunks = [];

for (const file of sourceFiles) {
  const source = await readFile(file, 'utf8');
  const bundled = source
    .replace(/^import(?:.|\r?\n)*?from\s+['"][^'"]+['"];\r?\n/gm, '')
    .replace(/^import\s+['"][^'"]+['"];\r?\n/gm, '')
    .replace(/^export\s+\{[^}]+\};?\r?\n/gm, '')
    .replace(/^export\s+(?=(?:class|const|function)\s)/gm, '');

  chunks.push(`// ---- ${file} ----\n${bundled.trim()}\n`);
}

const output = `// Generated by scripts/build-bundle.mjs.\n// This classic script also works when index.html is opened via file://.\n(() => {\n'use strict';\n\n${chunks.join('\n')}\n})();\n`;

await mkdir('.', { recursive: true });
await writeFile('app.js', output, 'utf8');

const bundleStart = '<!-- APP_BUNDLE_START -->';
const bundleEnd = '<!-- APP_BUNDLE_END -->';
const bundlePattern = /<!-- APP_BUNDLE_START -->[\s\S]*?<!-- APP_BUNDLE_END -->/;
const html = await readFile('index.html', 'utf8');

if (!bundlePattern.test(html)) {
  throw new Error('Bundle markers are missing from index.html');
}

const inlineOutput = output.replace(/<\/script/gi, '<\\/script');
const inlineBundle = `${bundleStart}\n<script>\n${inlineOutput}</script>\n${bundleEnd}`;

await writeFile('index.html', html.replace(bundlePattern, inlineBundle), 'utf8');
